#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    int findTheLongestSubstring(std::string s) {
        std::vector<int> seen(32, -2);
        seen[0] = -1;
        int mask = 0, maxLen = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            char ch = s[i];
            if (ch == 'a') mask ^= 1;
            else if (ch == 'e') mask ^= 2;
            else if (ch == 'i') mask ^= 4;
            else if (ch == 'o') mask ^= 8;
            else if (ch == 'u') mask ^= 16;
            if (seen[mask] != -2) {
                maxLen = std::max(maxLen, i - seen[mask]);
            } else {
                seen[mask] = i;
            }
        }
        return maxLen;
    }
};

import java.util.*;

class Solution {
    public int findTheLongestSubstring(String s) {
        int[] seen = new int[32];
        Arrays.fill(seen, -2);
        seen[0] = -1;
        int mask = 0, maxLen = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == 'a') mask ^= 1;
            else if (ch == 'e') mask ^= 2;
            else if (ch == 'i') mask ^= 4;
            else if (ch == 'o') mask ^= 8;
            else if (ch == 'u') mask ^= 16;
            if (seen[mask] != -2) {
                maxLen = Math.max(maxLen, i - seen[mask]);
            } else {
                seen[mask] = i;
            }
        }
        return maxLen;
    }
}

var findTheLongestSubstring = function(s) {
    const seen = new Array(32).fill(-2);
    seen[0] = -1;
    let mask = 0, maxLen = 0;
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (ch === "a") mask ^= 1;
        else if (ch === "e") mask ^= 2;
        else if (ch === "i") mask ^= 4;
        else if (ch === "o") mask ^= 8;
        else if (ch === "u") mask ^= 16;
        if (seen[mask] !== -2) {
            maxLen = Math.max(maxLen, i - seen[mask]);
        } else {
            seen[mask] = i;
        }
    }
    return maxLen;
};
